:root {
    --layout-max-width: 1400px;
    --layout-news-columns: repeat(auto-fill, minmax(380px, 1fr));
    --layout-card-gap: 3rem;
    --layout-card-direction: column;
    --layout-animation-style: crystalline-entry;
    --prism-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
    --prism-accent-glow: 0 0 15px var(--morpho-accent-primary);
}

#news-container {
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    max-width: var(--layout-max-width);
    margin: 6rem auto;
    padding: 0 2rem;
    perspective: 2000px;
}

.news-card {
    /* Grid Subgrid Implementation */
    grid-row: span 4;
    display: grid;
    grid-template-rows: subgrid;
    row-gap: 1rem;

    position: relative;
    background: rgba(var(--morpho-bg-secondary-rgb), 0.5);
    backdrop-filter: blur(20px);
    border: 1px solid rgba(var(--morpho-accent-primary-rgb), 0.15);
    border-radius: 4px;
    padding: 2rem;

    /* 3D Property */
    transform-style: preserve-3d;
    transition: 
        transform 0.8s cubic-bezier(0.16, 1, 0.3, 1),
        box-shadow 0.8s ease,
        border-color 0.4s ease,
        opacity 1s ease-out,
        translate 1s ease-out;

    /* Modern CSS: Starting Style for entry animation */
    opacity: 1;
    translate: 0 0;
}

@starting-style {
    .news-card {
        opacity: 0;
        translate: 0 50px;
    }
